<?php $e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$v=static fn(string $k):string=>$e($values[$k]??''); ?>
<div class="page-heading"><div><h1><?= $e($title) ?></h1><p>Leave slug empty to generate it from the name.</p></div><a href="/admin/brands">Back to brands</a></div>
<?php if($errors):?><div class="flash flash-error" role="alert"><strong>Please correct the highlighted fields.</strong></div><?php endif;?>
<form class="panel admin-form" method="post" action="<?= $e($action) ?>"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>">
<?php foreach(['name'=>'Name','slug'=>'Slug','seo_title'=>'SEO title'] as $key=>$label):?><label><?= $e($label) ?><input name="<?= $e($key) ?>" value="<?= $v($key) ?>" maxlength="<?= $key==='name'?150:($key==='slug'?180:255) ?>" <?= $key==='name'?'required':'' ?>><?php if(isset($errors[$key])):?><span class="field-error"><?= $e($errors[$key]) ?></span><?php endif;?></label><?php endforeach;?>
<label>SEO description<textarea name="seo_description" maxlength="320" rows="3"><?= $v('seo_description') ?></textarea><?php if(isset($errors['seo_description'])):?><span class="field-error"><?= $e($errors['seo_description']) ?></span><?php endif;?></label><label class="check"><input type="checkbox" name="is_active" value="1" <?= (int)($values['is_active']??1)===1?'checked':'' ?>> Active</label><button type="submit">Save brand</button></form>
